import{_ as e,C as t,c as r,o as n,j as i,b as l,a0 as d,a,w as s,G as g,a1 as o}from"./chunks/framework.DKRgXLPU.js";const k=JSON.parse('{"title":"Lage treningsplanen din","description":"","frontmatter":{},"headers":[],"relativePath":"no/education/goals/planning.md","filePath":"no/education/goals/planning.md"}');const u=e({name:"no/education/goals/planning.md"},[["render",function(e,k,u,m,p,h){const v=t("Mermaid");return n(),r("div",null,[k[1]||(k[1]=i("h1",{id:"lage-treningsplanen-din",tabindex:"-1"},[a("Lage treningsplanen din "),i("a",{class:"header-anchor",href:"#lage-treningsplanen-din","aria-label":'Permalink to "Lage treningsplanen din"'},"​")],-1)),k[2]||(k[2]=i("p",null,"Mål uten en plan er bare ønsker. Denne veiledningen hjelper deg med å gjøre målene dine om til en strukturert treningsplan som faktisk fungerer.",-1)),k[3]||(k[3]=i("div",{class:"tip custom-block"},[i("p",{class:"custom-block-title"},"Den store ideen"),i("p",null,[i("strong",null,"Mål uten en plan er bare ønsker."),a(" En strukturert treningsplan forvandler målene dine til daglige handlinger som resulterer i reell fremgang.")])],-1)),(n(),l(o,null,{default:s(()=>[g(v,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BM%C3%A5l%5D%20--%3E%20B%5BTreningsplan%5D%0A%20%20%20%20B%20--%3E%20C%5BDaglige%20handlinger%5D%0A%20%20%20%20C%20--%3E%20D%5BKonsekvent%20praksis%5D%0A%20%20%20%20D%20--%3E%20E%5BM%C3%A5lbar%20fremgang%5D%0A%20%20%20%20E%20--%3E%20F%5BM%C3%A5loppn%C3%A5else%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23e8f5e9%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:s(()=>[...k[0]||(k[0]=[a(" Loading... ",-1)])]),_:1})),k[4]||(k[4]=d('<h2 id="de-8-fasene-av-selvstyrt-utvikling" tabindex="-1">De 8 fasene av selvstyrt utvikling <a class="header-anchor" href="#de-8-fasene-av-selvstyrt-utvikling" aria-label="Permalink to &quot;De 8 fasene av selvstyrt utvikling&quot;">​</a></h2><h3 id="fase-1-sett-kompasset-ditt-mal" tabindex="-1">Fase 1: Sett kompasset ditt (mål) <a class="header-anchor" href="#fase-1-sett-kompasset-ditt-mal" aria-label="Permalink to &quot;Fase 1: Sett kompasset ditt (mål)&quot;">​</a></h3><p>Du har allerede lært om SMART-mål. Nå kan du sette dem i et hierarki:</p><ol><li><strong>Langsiktig mål</strong> (1–2 år): Din drøm</li><li><strong>Årlig mål</strong>: Årets mål</li><li><strong>Kvartalsvise mål</strong>: 3-måneders milepæler</li><li><strong>Månedlige mål</strong>: Spesifikke fokusområder</li><li><strong>Ukentlige mål</strong>: Treningsmål</li></ol><h3 id="fase-2-vurder-ressursene-dine" tabindex="-1">Fase 2: Vurder ressursene dine <a class="header-anchor" href="#fase-2-vurder-ressursene-dine" aria-label="Permalink to &quot;Fase 2: Vurder ressursene dine&quot;">​</a></h3><p>Før du planlegger, bør du ærlig vurdere hva du har:</p><table tabindex="0"><thead><tr><th>Ressurs</th><th>Spørsmål å stille</th></tr></thead><tbody><tr><td><strong>Tid</strong></td><td>Hvor mange timer i uken kan du realistisk sett trene?</td></tr><tr><td><strong>Sted</strong></td><td>Har du tilgang til en skikkelig løype? Hvordan er kvaliteten på underlaget?</td></tr><tr><td><strong>Utstyr</strong></td><td>Har du passende boule? Måleverktøy? Videofunksjon?</td></tr><tr><td><strong>Kunnskap</strong></td><td>Hva er dine tekniske styrker og svakheter?</td></tr><tr><td><strong>Fysisk tilstand</strong></td><td>Noen begrensninger? Områder som trenger arbeid?</td></tr></tbody></table><p>Vær ærlig. En realistisk plan slår en ambisiøs fantasi.</p><h3 id="fase-3-velg-øvelsene-dine" tabindex="-1">Fase 3: Velg øvelsene dine <a class="header-anchor" href="#fase-3-velg-øvelsene-dine" aria-label="Permalink to &quot;Fase 3: Velg øvelsene dine&quot;">​</a></h3><p>Velg øvelser som direkte støtter målene dine:</p><p><strong>For forbedring av poengsetting:</strong></p><ul><li>Presisjonspekking til markerte soner</li><li>Avstandsvariasjonsøvelser</li><li>Ulike overflateøvelser</li></ul><p><strong>For forbedring av skyting:</strong></p><ul><li>Skytestige (progressive distanser)</li><li>Hindringsskyting (tvungen høy bue)</li><li>Øving av bevegelige mål</li></ul><p><strong>For mental utvikling:</strong></p><ul><li>Rutinemessig trening før skudd</li><li>Visualiseringsøkter</li><li>Trykksimulering</li></ul><p><strong>Balanser programmet ditt:</strong></p><ul><li>Teknisk arbeid (peking, skyting)</li><li>Mental trening (mindfulness, visualisering)</li><li>Fysisk kondisjon (balanse, fleksibilitet)</li><li>Matchspill (bruke ferdigheter)</li></ul><h3 id="fase-4-lag-timeplanen-din" tabindex="-1">Fase 4: Lag timeplanen din <a class="header-anchor" href="#fase-4-lag-timeplanen-din" aria-label="Permalink to &quot;Fase 4: Lag timeplanen din&quot;">​</a></h3><p>Lag en realistisk ukeplan:</p><table tabindex="0"><thead><tr><th>Dag</th><th>Morgen</th><th>Ettermiddag</th><th>Kveld</th><th>Fokus</th></tr></thead><tbody><tr><td>man</td><td>-</td><td>Teknisk: Peking</td><td>Lett mobilitet</td><td>Presisjon</td></tr><tr><td>tirsdag</td><td>-</td><td>Teknisk: Skyting</td><td>-</td><td>Kraft/nøyaktighet</td></tr><tr><td>Ons</td><td>-</td><td>Mental trening</td><td>-</td><td>Mindfulness</td></tr><tr><td>Torsdag</td><td>-</td><td>Blandet: Spillscenarier</td><td>Lett mobilitet</td><td>Søknad</td></tr><tr><td>Fre</td><td>-</td><td>Teknisk: Svakhet</td><td>-</td><td>Forbedring</td></tr><tr><td>Lør</td><td>Matchspill eller konkurranse</td><td>-</td><td>-</td><td>Ytelse</td></tr><tr><td>Sol</td><td>Hvile</td><td>Ukentlig gjennomgang</td><td>Planlegging</td><td>Bedring</td></tr></tbody></table><p><strong>Nøkkelprinsipper:</strong></p><ul><li>Prioriter mental trening (det blir ofte neglisjert)</li><li>Inkluder hviledager</li><li>Balanser ulike ferdigheter</li><li>La fleksibilitet være der for livet</li></ul><h3 id="fase-5-forbered-deg-pa-hindringer" tabindex="-1">Fase 5: Forbered deg på hindringer <a class="header-anchor" href="#fase-5-forbered-deg-pa-hindringer" aria-label="Permalink to &quot;Fase 5: Forbered deg på hindringer&quot;">​</a></h3><p>Ting vil gå galt. Planlegg for det.</p><table tabindex="0"><thead><tr><th>Fare</th><th>Sannsynlighet</th><th>Påvirkning</th><th>Sikkerhetskopieringsplan</th></tr></thead><tbody><tr><td>Tidsmangel</td><td>Høy</td><td>Medium</td><td>Ha en &quot;minimumsøkt&quot; klar (20 min)</td></tr><tr><td>Dårlig vær</td><td>Medium</td><td>Medium</td><td>Innendørs visualisering, videostudie</td></tr><tr><td>Lav motivasjon</td><td>Høy</td><td>Medium</td><td>Gå tilbake til «hvorfor», mindre mål, ta en pause</td></tr><tr><td>Mindre skade</td><td>Medium</td><td>Høy</td><td>Fokus på mental trening, upåvirkede ferdigheter</td></tr><tr><td>Ingen øvingspartner</td><td>Medium</td><td>Lav</td><td>Soloøvelser, video selvanalyse</td></tr></tbody></table><h3 id="fase-6-spor-fremgangen-din" tabindex="-1">Fase 6: Spor fremgangen din <a class="header-anchor" href="#fase-6-spor-fremgangen-din" aria-label="Permalink to &quot;Fase 6: Spor fremgangen din&quot;">​</a></h3><p>Det som blir målt, blir styrt.</p><p><strong>Før treningsdagbok:</strong></p><ul><li>Dato og varighet</li><li>Øvelser fullført</li><li>Poeng/resultater</li><li>Hvordan du følte deg (energi, fokus, flyt)</li><li>Tekniske notater</li><li>Vær/forhold</li></ul><p><strong>Ukentlige oppsummeringsspørsmål:</strong></p><ul><li>Fullførte jeg de planlagte øktene mine?</li><li>Hvilke poengsummer oppnådde jeg?</li><li>Hva føltes bra? Hva var vanskelig?</li><li>Noen erfaringer med flyt?</li><li>Hva bør jeg justere?</li></ul><h3 id="fase-7-hold-deg-motivert" tabindex="-1">Fase 7: Hold deg motivert <a class="header-anchor" href="#fase-7-hold-deg-motivert" aria-label="Permalink to &quot;Fase 7: Hold deg motivert&quot;">​</a></h3><p>Motivasjonen svinger. Bygg systemer for å opprettholde den:</p><p><strong>Indre motivasjon:</strong></p><ul><li>Koble deg til ditt «hvorfor»</li><li>Feir små seire</li><li>Legg merke til forbedring over tid</li><li>Finn glede i prosessen</li></ul><p><strong>Ekstern støtte:</strong></p><ul><li>Treningspartnere (selv av og til)</li><li>Del mål med noen</li><li>Bli med i nettsamfunn</li><li>Sporstriper og konsistens</li></ul><p><strong>Når motivasjonen synker:</strong></p><ul><li>Gjør en minimumsøkt (noe slår ingenting)</li><li>Endre miljøet ditt</li><li>Gjennomgå fremgangen din</li><li>Husk tidligere suksesser</li><li>Ta en planlagt pause om nødvendig</li></ul><h3 id="fase-8-gjennomgang-og-tilpasning" tabindex="-1">Fase 8: Gjennomgang og tilpasning <a class="header-anchor" href="#fase-8-gjennomgang-og-tilpasning" aria-label="Permalink to &quot;Fase 8: Gjennomgang og tilpasning&quot;">​</a></h3><p>Planen din bør utvikle seg:</p><p><strong>Ukentlig:</strong> Rask gjennomgang, mindre justeringer <strong>Månedlig:</strong> Vurder fremdriften mot månedlige mål, juster fokus <strong>Kvartalsvis:</strong> Stor gjennomgang, sett mål for neste kvartal <strong>Årlig:</strong> Full vurdering, ny årsplan</p><p><strong>Spørsmål til gjennomgang:</strong></p><ul><li>Gjør jeg fremskritt mot målene mine?</li><li>Er treningen min effektiv?</li><li>Trenger jeg forskjellige øvelser?</li><li>Er målene mine fortsatt relevante?</li><li>Hva har jeg lært?</li></ul><h2 id="eksempel-pa-8-ukers-plan" tabindex="-1">Eksempel på 8-ukers plan <a class="header-anchor" href="#eksempel-pa-8-ukers-plan" aria-label="Permalink to &quot;Eksempel på 8-ukers plan&quot;">​</a></h2><p><strong>Mål:</strong> Forbedre skytepresisjonen med 15 %</p><table tabindex="0"><thead><tr><th>Uke</th><th>Fokus</th><th>Viktige økter</th></tr></thead><tbody><tr><td>1</td><td>Grunnlinje</td><td>Test strømnivå, videoanalyse</td></tr><tr><td>2</td><td>Teknikk</td><td>Identifisere og jobbe med hovedproblemet</td></tr><tr><td>3</td><td>Gjentakelse</td><td>Skyteøvelse med høyt volum</td></tr><tr><td>4</td><td>Test</td><td>Midtveisvurdering, juster</td></tr><tr><td>5</td><td>Variasjon</td><td>Ulike avstander og vinkler</td></tr><tr><td>6</td><td>Trykk</td><td>Legg til konsekvenser for øvelser</td></tr><tr><td>7</td><td>Integrering</td><td>Spilllignende scenarier</td></tr><tr><td>8</td><td>Sluttprøve</td><td>Mål forbedring</td></tr></tbody></table><h2 id="viktig-konklusjon" tabindex="-1">Viktig konklusjon <a class="header-anchor" href="#viktig-konklusjon" aria-label="Permalink to &quot;Viktig konklusjon&quot;">​</a></h2><blockquote><p>Planlegg arbeidet ditt, og utarbeid deretter planen din. Men vær forberedt på å tilpasse deg.</p></blockquote><p>Den beste planen er en du faktisk følger. Start enkelt, vær konsekvent og juster etter hvert som du lærer.</p>',51))])}]]);export{k as __pageData,u as default};
